// Editor de páginas de Delulu Journal V2 (repositorio delulusV2), adaptado a Hojea.
// Lo de abajo de "Código de Delulu" es el original; este encabezado lo conecta con el almacenamiento de Hojea.
import { confirmDialog, toast as showToast } from './ui.js';
import { COW_SPOTS, charmSVG, engraveColor, paintFur } from './cover.js';
import { cowStickers } from './cow.js';
import { deleteMeta, getMeta, getMetaByPrefix, getPageUrl, saveBook, setMeta } from './db.js';

let S = null;
const HOOKS = { back: null, cover: null };
const toast = (msg) => showToast(msg);
const confirmBox = (title, text, ok, fn) => { confirmDialog(title, text, ok).then((yes) => { if (yes) fn(); }); };
const touch = () => matchMedia('(pointer: coarse)').matches;
const seenTips = new Set();
function tipOnce(key, msg) {
  if (seenTips.has(key)) return;
  seenTips.add(key);
  try {
    if (localStorage.getItem('hojea-tip-' + key)) return;
    localStorage.setItem('hojea-tip-' + key, '1');
  } catch { /* sin almacenamiento, el consejo solo se repite */ }
  toast(msg);
}
function go(screen) {
  document.getElementById('open').classList.toggle('show', screen === 'open');
  if (screen === 'home') HOOKS.back?.();
}
const openCover = (a) => HOOKS.cover?.(a);
const FL = { a: null, i: -1 };
const flipIdx = () => [];
const TORNASOL = '#e6e1ee';

// Tamaño de diseño de una página: siempre 560 de ancho, con la proporción de la hoja del libro.
const SHEET_RATIO = 0.976 / 0.956;
const dims = (a) => [560, Math.round(560 / ((a.aspect || 0.72) * SHEET_RATIO))];

// Fotos escaneadas del cuaderno: la página las muestra como base y encima van los elementos.
const SCANS = new Map();
const scanHTML = (p) => (p.scan && SCANS.get(p.scan) ? `<img class="pg-scan" decoding="async" src="${SCANS.get(p.scan)}" alt="" draggable="false">` : '');
async function drawScan(ctx, p, W, H) {
  if (!p.scan) return;
  const img = await loadImg(SCANS.get(p.scan));
  if (!img) return;
  const k = Math.min(W / img.naturalWidth, H / img.naturalHeight), w = img.naturalWidth * k, h = img.naturalHeight * k;
  ctx.drawImage(img, (W - w) / 2, (H - h) / 2, w, h);
}

// Guardado: los mismos pasos que V2, pero sobre la base de datos de Hojea.
let saveTimer = null;
async function flushSave() {
  clearTimeout(saveTimer);
  saveTimer = null;
  try {
    if (ED.a) await saveBook(ED.a);
    await setMeta('prefs', S.prefs);
  } catch {
    toast('No se pudo guardar: libera espacio o quita fotos grandes');
  }
}
function persist() {
  clearTimeout(saveTimer);
  saveTimer = setTimeout(flushSave, 400);
}
const imageStore = (init) => new Proxy({ ...init }, {
  set(o, k, v) { o[k] = v; setMeta('img:' + k, v).catch(() => toast('No se pudo guardar la foto. Libera espacio y vuelve a intentar.')); return true; },
  deleteProperty(o, k) { delete o[k]; deleteMeta('img:' + k); return true; },
});

