  const delta=b=>({l:[ref.x-b.x,0],r:[ref.x+ref.w-b.x-b.w,0],ch:[ref.x+ref.w/2-b.x-b.w/2,0],t:[0,ref.y-b.y],b:[0,ref.y+ref.h-b.y-b.h],cv:[0,ref.y+ref.h/2-b.y-b.h/2]})[k];
