export async function initDelulu() {
  const prefs = (await getMeta('prefs')) ?? {};
  S = { images: imageStore(await getMetaByPrefix('img:')), prefs: { favs: [], custom: [], ...prefs } };
  ED.snap = S.prefs.snap ?? true;
  updSnapBtn();
}
export async function ensureScans(book) {
  await Promise.all(book.pages.filter((p) => p.scan).map(async (p) => {
    if (!SCANS.has(p.scan)) SCANS.set(p.scan, await getPageUrl(p.scan));
  }));
}
export function openEditor(book, index, { tab, onBack, onCover } = {}) {
  HOOKS.back = onBack;
  HOOKS.cover = onCover;
  if (tab) V.libTab = tab;
  openAgenda(book, index);
}
export async function closeEditor() {
  deselect();
  closeSheet();
  ED.draw = null;
  $('#btnDraw').classList.remove('on');
  document.getElementById('open').classList.remove('show');
  await flushSave();
  ED.a = null;
}
export function pageSurfaceHTML(p, book) {
  const [W, H] = dims(book);
  return `<div class="pg-surface" style="width:${W}px;height:${H}px;${bgCSS(p.bg)}">${scanHTML(p)}<div class="els" style="position:absolute;inset:0">${elsHTML(p.elements)}</div></div>`;
}
export const pageThumbHTML = (p, book, width) => { const [W, H] = dims(book); return miniPage(p, W, H, width); };
export const newBlankPage = () => pg('lines');
export const forgetScan = (id) => SCANS.delete(id);
export function deleteImagesOf(book, otherBooks) {
  const ids = (x) => JSON.stringify(x).match(/img_[a-z0-9]+/g) ?? [];
  const keep = new Set([...ids(otherBooks), ...S.prefs.custom]);
  ids(book).forEach((id) => { if (!keep.has(id) && S.images[id]) delete S.images[id]; });
}
// Traduce la portada de Hojea al formato que dibuja la exportación de V2.
export async function prepareExport(book) {
  await ensureScans(book);
  const c = book.cover, [W, H] = dims(book), elements = [], t = c.title;
  const textFx = (fx) => {
    if (fx === 'impreso') return { fx: '', color: t.color };
    const dark = fx === 'grabado' ? engraveColor(c.color) : null;
    return dark ? { fx: '', color: dark } : { fx };
  };
  if (t.show && book.title) {
    const fs = Math.min(46, Math.max(26, 560 / Math.max(8, book.title.length))) * t.size;
    elements.push({ id: 'title', type: 'text', text: book.title, x: W * 0.08, y: H * t.y, w: W * 0.7, h: fs * 3, r: 0, font: t.font, fs, it: t.italic, al: 'center', ...textFx(t.fx) });
  }
  const initials = (c.initials.text || '').trim().toUpperCase().slice(0, 3);
  if (initials) elements.push({ id: 'ini', type: 'text', text: initials, x: W * 0.6, y: H * 0.875, w: W * 0.2, h: 40, r: 0, font: '"Bodoni Moda", serif', fs: 22, al: 'center', ...textFx(c.initials.fx) });
  const photoURL = c.photoId ? await getPageUrl(c.photoId) : null;
  return { ...book, name: book.title, cover: { ...c, elements, photoURL } };
}
